<script>
document.addEventListener("DOMContentLoaded", function () {
  const track = document.querySelector(".news-track");
  const previous = document.getElementById("news-prev");
  const next = document.getElementById("news-next");

  if (!track || !previous || !next) return;

  let items = Array.from(track.querySelectorAll(".news-item"));
  if (!items.length) return;

  // Clone first and last items for seamless looping
  const firstClone = items[0].cloneNode(true);
  const lastClone = items[items.length - 1].cloneNode(true);

  firstClone.classList.add("clone");
  lastClone.classList.add("clone");

  track.insertBefore(lastClone, items[0]);
  track.appendChild(firstClone);

  items = Array.from(track.querySelectorAll(".news-item"));

  // Start on the first real item, because index 0 is the last clone
  let current = 1;

  function setPosition(animated = true) {
    track.style.transition = animated ? "transform 0.45s ease" : "none";
    track.style.transform = `translateX(-${current * 100}%)`;
  }

  setPosition(false);

  function moveLeft() {
    current += 1;
    setPosition(true);
  }

  function moveRight() {
    current -= 1;
    setPosition(true);
  }

  previous.addEventListener("click", function (event) {
  event.preventDefault();
  moveRight();
});

next.addEventListener("click", function (event) {
  event.preventDefault();
  moveLeft();
});

  track.addEventListener("transitionend", function () {
    // If we moved before the first real item, jump to the last real item
    if (current === 0) {
      current = items.length - 2;
      setPosition(false);
    }

    // If we moved after the last real item, jump to the first real item
    if (current === items.length - 1) {
      current = 1;
      setPosition(false);
    }
  });
});
</script>

